#!/usr/bin/env python3
"""Vow: No AI attribution in commits (Hard layer).

PreToolUse hook that blocks (or warns in shadow mode) when a
`git commit` command contains AI attribution strings such as
"Co-authored-by: Claude", "Generated by Claude", "AI-assisted",
or the robot emoji.

Shadow mode is ON by default (warn only).  Set VOW_SHADOW_MODE=0
to switch to full blocking.
"""

from __future__ import annotations

import json
import re
import sys
import unicodedata
from pathlib import Path

# D-06: shadow_mode and is_git_commit are in shared/vow_utils.
sys.path.insert(0, str(Path(__file__).parent))
from shared.vow_utils import (  # noqa: E402 - hook script must inject sys.path before importing sibling shared/ module
    git_commit_message_offset,
    git_commit_offset,
    is_git_commit,
    shadow_mode_active,
    vow_output,
)

# Known AI coding tools. Extending coverage (Codeium, Cody, Tabnine,
# Windsurf, Devin, Sweep, etc.) is a one-line change in these two lists;
# the regexes below consume them at module load.
_AI_TOOL_NAMES = ["Claude", "Anthropic", "Cursor", "Copilot"]
_AI_TOOL_DOMAINS = [r"claude\.ai", r"anthropic\.com", r"cursor\.(?:sh|com)"]

_TOOL_NAME_GROUP = "|".join(_AI_TOOL_NAMES)
_TOOL_DOMAIN_GROUP = "|".join(_AI_TOOL_DOMAINS)

# Strong attribution verbs: trailer keywords and canonical prose that
# always signal credit assignment. A tool name on the same line as one
# of these is unambiguous AI attribution.
_STRONG_ATTRIBUTION_PREFIX = (
    r"Co-authored(?:-by)?"
    r"|Generated\s+by"
    r"|Authored\s+by"
    r"|Approved\s+by"
    r"|Signed-off-by"
    r"|Composed\s+by"
    r"|Written\s+by"
    r"|Created\s+by"
    r"|Reviewed\s+by"
    r"|Verified\s+by"
)

# Patterns that indicate AI attribution in a commit message.
#
# Every pattern requires an ATTRIBUTION CONTEXT: a trailer keyword, an
# attribution verb, or an explicit marker. Bare tool names and URLs
# ("chore: bump anthropic>=0.40", "docs: link to anthropic.com", "fix:
# cursor positioning") do NOT match, which is the false-positive class
# documented in PR #417 review finding B1.
#
# A verb and the tool it credits must share a line. Each line is searched
# once for its first verb and once for a tool after it: a lazy `[^\n]*?`
# retried from every verb was quadratic, and a 45 KB message took 7
# seconds against a hook killed at 2, which the harness treats as allow.
_TOOL_NAME_RE = re.compile(rf"\b(?:{_TOOL_NAME_GROUP})\b", re.IGNORECASE)
_TOOL_DOMAIN_RE = re.compile(rf"\b(?:{_TOOL_DOMAIN_GROUP})\b", re.IGNORECASE)
# Strong verb where a trailer or credit line starts: a line start, a `\n`
# escape inside a $'...' string, or a message flag (-m, -am, --message,
# --trailer, spaced, attached or with `=`) and its optional quote. Mid-line
# is prose and passes, "Co-authored-by" included: only the commit's own
# message text is anchored, so an echo chained after it is not read.
# A flag starts after whitespace, so `-system` and `custom-form` in prose
# are not `-m`; a $'...' newline counts only as the message's own text.
_FLAG = r"(?<![\w-])(?:-[a-zA-Z]*m|--message|--trailer)(?:\s+|=)?"
# A here-string (`git commit -F - <<< $'...'`) is the message too.
_ANSI_C_OWNER = rf"(?:{_FLAG}|<<<\s*)"
_STRONG_VERB_RE = re.compile(
    rf"(?:^|{_ANSI_C_OWNER}\$'[^'\n]*\\n|{_FLAG}\$?['\"]?)"
    rf"\s*(?:{_STRONG_ATTRIBUTION_PREFIX})",
    re.IGNORECASE,
)
# Weak verb (by/from/via) before a known tool domain. Domains are
# attribution-unambiguous even with weak verbs: "by claude.ai".
_WEAK_VERB_RE = re.compile(r"\b(?:by|from|via)\b", re.IGNORECASE)
# The GitHub Copilot bot trailer ("[bot]" is explicit), generic markers,
# and the robot emoji.
_MARKER_RE = re.compile(
    r"\bgithub-copilot\[bot\]|\bAI-assisted\b|\U0001F916", re.IGNORECASE
)
# Every pattern above needs one of these, so a message without any is
# clean after one linear pass.
_LITERALS = [name.lower() for name in _AI_TOOL_NAMES] + ["ai-assisted", "\U0001f916"]

# Text piped into `git commit -F -` starts a line after a `\n` escape or
# the opening quote of the printf or echo that prints it. Only the feeding
# commands are read this way: an echo chained after the commit is not the
# message.
_FEEDER_VERB_RE = re.compile(
    r"(?:\\n|\b(?:printf|echo)(?:\s+-\w+)*\s+['\"])"
    rf"\s*(?:{_STRONG_ATTRIBUTION_PREFIX})",
    re.IGNORECASE,
)


def _verb_then_tool(
    verb_re: re.Pattern[str], tool_re: re.Pattern[str], text: str
) -> bool:
    """Return True if a line of *text* has a verb with a tool after it."""
    for line in text.split("\n"):
        verb = verb_re.search(line)
        if verb and tool_re.search(line, verb.end()):
            return True
    return False


def _visible(text: str) -> str:
    """Drop Unicode format (Cf) characters.

    A zero-width space or word joiner renders as nothing, so "Cl\u200baude"
    reads as Claude to a person but matched no pattern.
    """
    if text.isascii():
        return text
    return "".join(char for char in text if unicodedata.category(char) != "Cf")


def _has_ai_attribution(command: str) -> bool:
    """Return True if *command* contains an AI attribution string."""
    command = _visible(command)
    lowered = command.lower()
    if not any(literal in lowered for literal in _LITERALS):
        return False
    return bool(
        _MARKER_RE.search(command)
        or _verb_then_tool(_STRONG_VERB_RE, _TOOL_NAME_RE, command)
        or _verb_then_tool(_WEAK_VERB_RE, _TOOL_DOMAIN_RE, command)
    )


def _has_feeder_trailer(feeders: str) -> bool:
    """Return True if the commands piped into the commit print a trailer."""
    return _verb_then_tool(_FEEDER_VERB_RE, _TOOL_NAME_RE, _visible(feeders))


def main() -> None:
    """Entry point for the PreToolUse hook."""
    try:
        raw = sys.stdin.read()
        data = json.loads(raw)
    except (json.JSONDecodeError, OSError):
        sys.exit(0)

    try:
        tool_name = data.get("tool_name", "")
        if tool_name != "Bash":
            sys.exit(0)

        command = data.get("tool_input", {}).get("command", "")
        if not is_git_commit(command):
            sys.exit(0)

        # Only the message: an earlier segment such as `printf ... >
        # notes.txt &&` is not part of it, while text piped into
        # `git commit -F -` is.
        message_offset = git_commit_message_offset(command) or 0
        feeders = command[message_offset : git_commit_offset(command)]
        if not (
            _has_ai_attribution(command[message_offset:])
            or _has_feeder_trailer(feeders)
        ):
            sys.exit(0)

        shadow = shadow_mode_active()
        decision = "warn" if shadow else "block"
        reason = (
            "Vow violation: AI attribution detected in commit message. "
            "Night Market vow prohibits AI attribution strings in commits "
            "(Hard vow). "
            + (
                "Shadow mode active -- this will block once VOW_SHADOW_MODE=0."
                if shadow
                else ""
            )
        )

        output = vow_output(enforce=decision == "block", reason=reason)
        print(json.dumps(output))
        print(
            f"[vow-no-ai-attribution] {decision.upper()}: AI attribution in commit",
            file=sys.stderr,
        )
        sys.exit(0)

    except Exception as exc:  # hook must not crash the agent under any circumstance
        print(f"[vow-no-ai-attribution] internal error: {exc}", file=sys.stderr)
        sys.exit(0)


if __name__ == "__main__":
    main()
